import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt();
        int[] a = new int[n * m];
        for (int i = 0; i < n * m; i++) a[i] = nextInt();
        int answer = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (a[i * m + j] != 0) {
                    answer += 4;
                    // each edge shared with the land above or to the left is interior
                    if (i > 0 && a[(i - 1) * m + j] != 0) answer -= 2;
                    if (j > 0 && a[i * m + j - 1] != 0) answer -= 2;
                }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, m := next(), next()
	a := make([]int, n*m)
	for i := range a {
		a[i] = next()
	}
	answer := 0
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if a[i*m+j] == 0 {
				continue
			}
			answer += 4
			// each edge shared with the land above or to the left is interior
			if i > 0 && a[(i-1)*m+j] != 0 {
				answer -= 2
			}
			if j > 0 && a[i*m+j-1] != 0 {
				answer -= 2
			}
		}
	}
	fmt.Println(answer)
}
